def _with_skin(html, skin):
    """يحقن الخط وطبقة التصميم (سبيكة) في آخر وسم style، فتغلب على ما قبلها."""
    d = Path(__file__).resolve().parent / "templates"
    extra = "".join((d / f).read_text(encoding="utf-8") for f in ("fonts.css", skin) if (d / f).is_file())
    i = html.rfind("</style>")
    return html if i < 0 or not extra else html[:i] + "\n" + extra + html[i:]


def load_template():
    p = Path(__file__).resolve().parent / "templates" / "office.html"
    if p.is_file():
        return _with_skin(p.read_text(encoding="utf-8"), "skin office.css")
    if _TEMPLATE_Z:
        import base64
        import zlib
        return zlib.decompress(base64.b64decode(_TEMPLATE_Z)).decode("utf-8")
    die("Site template not found")


def load_wizard():
    p = Path(__file__).resolve().parent / "templates" / "wizard.html"
    if p.is_file():
        return _with_skin(p.read_text(encoding="utf-8"), "skin wizard.css").replace("@@LANGS@@", json.dumps(LANGUAGES, ensure_ascii=False))
    if _WIZARD_Z:
        import base64
        import zlib
        return zlib.decompress(base64.b64decode(_WIZARD_Z)).decode("utf-8")
    die("Creation wizard not found")


def single_source():
    """نص الأداة كملف واحد مكتفٍ بنفسه (القالبان مضغوطان بداخله)."""
    src = Path(__file__).resolve().read_text(encoding="utf-8")
    if _TEMPLATE_Z:
        return src
    import base64
    import textwrap
    import zlib
    for var, loader in (("_TEMPLATE_Z", load_template), ("_WIZARD_Z", load_wizard)):
        marker = var + " = None"
        i = src.find(marker)
        if i < 0:
            continue
        j = src.index("\n", i)
        z = base64.b64encode(zlib.compress(loader().encode("utf-8"), 9)).decode("ascii")
        src = src[:i] + '%s = """\n%s\n"""' % (var, "\n".join(textwrap.wrap(z, 110))) + src[j:]
    return src


